    "question": "Từ ngày 2/9/1945 đến ngày 19/12/1946, với phương châm Dĩ bất biến ứng vạn biến, giữ vững mục tiêu đấu tranh cho độc lập dân tộc, Hồ Chí Minh đã chỉ đạo thành công sách lược gì?",
