    "id": 65,
    "orig_no": "62",
    "question": "Đánh giá sau đây về Chủ tịch Hồ Chí Minh là của ai: “Hồ Chủ tịch là người sáng lập, lãnh đạo và rèn luyện Đảng ta, là người xây dựng nền Cộng hòa dân chủ Việt Nam và Mặt trận Dân tộc thống nhất, là người cha thân yêu của các lực lượng vũ trang nhân dân Việt Nam. Người là linh hồn, là ngọn cờ chói lọi, lãnh đạo toàn Đảng, toàn dân, toàn quân ta đoàn kết một lòng, chiến đấu anh dũng, viết nên những trang sử vẻ vang nhất của Tổ quốc ta”?",
