    "question": "Trong Lời kêu gọi toàn quốc kháng chiến (12-1946), Hồ Chí Minh viết: \"Bất kỳ đàn ông, đàn bà, (...) Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc\"26. Xác định cụm từ còn thiếu?",
