    "question": "Nhà nước của nhân dân là nhà nước mà tất cả mọi quyền lực trong nhà nước và trong xã hội đều thuộc về nhân dân. Quan điểm này của Hồ Chí Minh được thể hiện trong bản Hiến pháp nào?",
