    "orig_no": "45",
    "question": "Hồ Chí Minh luôn nêu cao tính nghiêm minh của pháp luật. Người từng bố: “Pháp luật Việt Nam tuy khoan hồng với những người biết cải tà quy chính, nhưng sẽ thẳng tay trừng trị những tên Việt gian đầu sỏ đã bán nước buôn dân”. Như vậy, Hồ Chí Minh đòi hỏi hệ thống pháp luật phải như thế nào?",
