    "question": "Luận điểm của Hồ Chí Minh: \"Lực lượng chủ yếu trong khối đại đoàn kết dân tộc là (...), cho nên liên minh (...) là nền tảng của Mặt trận dân tộc thống nhất\". Xác định cụm từ còn thiếu?",
