    "question": "Luận điểm: “Cũng như sông thì có nguồn mới có nước, không có nguồn thì sông cạn. Cây phải có gốc, không có gốc thì cây héo. Người cách mạng phải có (...), không có (...) thì dù tài giỏi mấy cũng không lãnh đạo được nhân dân”. Xác định cụm từ còn thiếu?",
